// HMAC-SHA256 of `${timestamp}.${body}`, 5-minute window (ADR 0002).
// The app signs JSON.stringify(payload), so re-serializing the parsed body reproduces it.
const crypto = require('crypto');
const { headers, body } = $input.first().json;
const secret = $env.N8N_SIGNING_SECRET;
const timestamp = headers['x-rn-timestamp'] ?? '';
const signature = headers['x-rn-signature'] ?? '';
const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${JSON.stringify(body)}`)
  .digest('hex');
const fresh = /^[0-9]+$/.test(timestamp) && Math.abs(Date.now() / 1000 - Number(timestamp)) <= 300;
const valid =
  fresh &&
  signature.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
return [{ json: { valid, context: body } }];

// Walking skeleton: 2 hard-coded Proposals. Ticket 04 replaces this with the AI agent.
const crypto = require('crypto');
const { context } = $('Verify signature').first().json;
const proposal = (title, summary, startHour) => ({
  title,
  summary,
  startAt: `2026-11-20T${startHour}:00:00+08:00`,
  endAt: `2026-11-20T${startHour + 2}:00:00+08:00`,
  estCostPerPerson: 30,
  venues: [{ name: `${title} spot` }],
  weatherNote: 'Stub: no forecast yet',
  rationale: 'Stub Proposal from the walking skeleton',
  source: 'ai',
});
const body = JSON.stringify({
  idempotencyKey: context.idempotencyKey,
  proposals: [
    proposal('Ramen and arcade', 'Slurp, then win tickets.', 18),
    proposal('Rooftop karaoke', 'Sing it like nobody is filming.', 20),
  ],
});
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto
  .createHmac('sha256', $env.N8N_SIGNING_SECRET)
  .update(`${timestamp}.${body}`)
  .digest('hex');
return [{ json: { callbackUrl: context.callbackUrl, body, timestamp, signature } }];
